    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"الحدود متساوية","math":"الحدود 6 متساوية، و جمع 6 حدود متساوية هو ضربها في 6"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> = 6 × 5<sup>5</sup></span>"},{"quoi":"نُظهر القاسم 15","math":"<span dir=\"ltr\" class=\"expr\">6 × 5<sup>5</sup> = 15 × (2 × 5<sup>4</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">15 × 2 × 5<sup>4</sup></span> و منه يقبل القسمة على 15"}],
