    correction: [{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">15 = 5 × 3</span> و العددان أوليان فيما بينهما"},{"quoi":"شرط القسمة على 5","math":"العدد يقبل القسمة على 5 إذا كان رقم آحاده 0 أو 5"},{"quoi":"نتحقّق من الشرط الأوّل","math":"نهاية العدد هي 0 و هي تقبل القسمة على 5"},{"quoi":"شرط القسمة على 3","math":"العدد يقبل القسمة على 3 إذا كان مجموع أرقامه يقبل القسمة على 3"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">3 + 9 + 6 + 4 + 9 + 5 + 2 + 5 + 5 + 0 = 48</span>"},{"quoi":"نتحقّق من الشرط الثاني","math":"48 يقبل القسمة على 3"},{"quoi":"النتيجة","math":"العدد يقبل القسمة على 5 و على 3 و هما أوليان فيما بينهما، فهو يقبل القسمة على 15"}],
