    correction: [{"quoi":"نوحّد الأساس","math":"<span dir=\"ltr\" class=\"expr\">9<sup>11</sup> = 3<sup>22</sup></span>"},{"quoi":"نعيد كتابة الجداء","math":"<span dir=\"ltr\" class=\"expr\">(3<sup>20</sup> - 9<sup>11</sup> × 81 = (3<sup>20</sup> - 3<sup>22</sup> × 81</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">(3<sup>20</sup> - 3<sup>22</sup> × 81 = 3<sup>20</sup>(1 - 3<sup>2</sup> × 81</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 3<sup>2</sup> = -8</span>"},{"quoi":"نضرب في 81","math":"<span dir=\"ltr\" class=\"expr\">-8 × 81 = -648</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">(3<sup>20</sup> - 9<sup>11</sup> × 81 = -648 × 3<sup>20</sup></span>"},{"quoi":"نُظهر القاسم 6","math":"<span dir=\"ltr\" class=\"expr\">-648 × 3<sup>20</sup> = 6 × ((-108) × 3<sup>20</sup></span>"},{"quoi":"الباقي","math":"الجداء مضاعف لـ 6 فباقي القسمة يساوي 0"},{"quoi":"الخارج","math":"الخارج هو <span dir=\"ltr\" class=\"expr\">(-108) × 3<sup>20</sup></span>"}],
