    correction: [{"quoi":"المبدأ","math":"نملأ المراكز الواحد بعد الآخر، ثمّ نضرب عدد الإختيارات"},{"quoi":"المركز 1","math":"كلّ الفرق ممكنة، أي 7 إختيارات"},{"quoi":"المركز 2","math":"بقي 6 إختيارات بعد شغل 1 من المراكز"},{"quoi":"نضرب الإختيارات","math":"<span dir=\"ltr\" class=\"expr\">7 × 6 = 42</span>"},{"quoi":"النتيجة","math":"عدد الإمكانيات هو 42"}],
